const frame = page.frames().find(f => f.url().includes('/tools/canvas-rce/index.html'));
if (!frame) return 'no frame; frames=' + page.frames().map(f=>f.url()).join(',');
await frame.evaluate(() => document.getElementById('theme-tray').showPopover());
await frame.waitForTimeout(300);
await frame.evaluate(() => document.getElementById('tab-js').click());
const after = await frame.evaluate(() => {
  const tabButtons = [...document.querySelectorAll('[role="tab"]')].map(b => ({id: b.id, selected: b.getAttribute('aria-selected')}));
  const panels = [...document.querySelectorAll('[role="tabpanel"]')].map(p => ({id: p.id, hidden: p.hidden}));
  const scripts = [...document.scripts].map(s => s.src || '(inline)');
  return { tabButtons, panels, scripts };
});
return JSON.stringify(after, null, 2);
